  if (hasExtension(intake, 'yaml', 'yml')) return 0.95;
  if (mimeMatches(intake, 'yaml', 'x-yaml')) return 0.9;
  const t = intake.textSample || '';
  if (/^---\s*$/m.test(t) && /^\s*[\w-]+:\s/m.test(t)) return 0.5;   // doc marker + a mapping
